"use client";

import { AnimatePresence, motion } from "motion/react";
import { useEffect, useRef, useState } from "react";

export function AlertDialogTailwind({ onConfirm }: { onConfirm?: () => void }) {
  const [open, setOpen] = useState(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const cancel = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    if (!open) return;
    cancel.current?.focus();
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
    document.addEventListener("keydown", onKey);
    return () => { document.removeEventListener("keydown", onKey); trigger.current?.focus(); };
  }, [open]);
  return (
    <>
      <button ref={trigger} onClick={() => setOpen(true)} className="h-9 rounded-lg border border-red-500/40 px-4 text-sm font-medium text-red-500 hover:bg-red-500/10">Delete account</button>
      <AnimatePresence>
        {open && (
          <div className="fixed inset-0 z-50 grid place-items-center p-4">
            <motion.div className="absolute inset-0 bg-black/60 backdrop-blur-sm" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} />
            <motion.div role="alertdialog" aria-modal="true" aria-labelledby="ad-title" aria-describedby="ad-desc" className="relative w-full max-w-md rounded-xl border border-zinc-800 bg-zinc-950 p-6 text-zinc-100" initial={{ opacity: 0, scale: 0.94, y: 10 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={{ opacity: 0, scale: 0.97 }} transition={{ duration: 0.22, ease: [0.16, 1, 0.3, 1] }}>
              <h2 id="ad-title" className="text-lg font-semibold">Are you absolutely sure?</h2>
              <p id="ad-desc" className="mt-2 text-sm text-zinc-400">This action cannot be undone.</p>
              <div className="mt-6 flex justify-end gap-2">
                <button ref={cancel} onClick={() => setOpen(false)} className="h-9 rounded-lg border border-zinc-800 px-4 text-sm">Cancel</button>
                <button onClick={() => { onConfirm?.(); setOpen(false); }} className="h-9 rounded-lg bg-red-500 px-4 text-sm font-medium text-white">Yes, delete account</button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </>
  );
}
